const test = require('node:test');
const assert = require('node:assert/strict');
const { createInventory, STORAGE_KEY } = require('./store.js');

function memoryStorage() {
  const data = new Map();
  return {
    getItem: (key) => (data.has(key) ? data.get(key) : null),
    setItem: (key, value) => {
      data.set(key, String(value));
    },
  };
}

test('add menyimpan nama yang dirapikan dan jumlah sebagai angka', () => {
  const inventory = createInventory(memoryStorage());

  const item = inventory.add({ nama: '  Kursi  ', jumlah: '12' });

  assert.equal(item.nama, 'Kursi');
  assert.equal(item.jumlah, 12);
  assert.deepEqual(inventory.list(), [item]);
});

test('add menerima jumlah 0', () => {
  const inventory = createInventory(memoryStorage());

  const item = inventory.add({ nama: 'Pensil', jumlah: 0 });

  assert.equal(item.jumlah, 0);
});

test('setiap barang yang ditambahkan memiliki id berbeda', () => {
  const inventory = createInventory(memoryStorage());

  const first = inventory.add({ nama: 'Meja', jumlah: 1 });
  const second = inventory.add({ nama: 'Meja', jumlah: 1 });

  assert.notEqual(first.id, second.id);
  assert.equal(inventory.list().length, 2);
});

test('add menolak nama kosong atau hanya berisi spasi', () => {
  const inventory = createInventory(memoryStorage());

  assert.throws(() => inventory.add({ nama: '   ', jumlah: 1 }), {
    message: 'Nama barang wajib diisi.',
  });
  assert.deepEqual(inventory.list(), []);
});

test('add menolak nama lebih dari 100 karakter', () => {
  const inventory = createInventory(memoryStorage());

  assert.throws(() => inventory.add({ nama: 'a'.repeat(101), jumlah: 1 }), {
    message: 'Nama barang maksimal 100 karakter.',
  });
});

test('add menolak jumlah yang bukan bilangan bulat 0 atau lebih', () => {
  const inventory = createInventory(memoryStorage());

  for (const jumlah of [-1, 1.5, '', 'abc', null]) {
    assert.throws(() => inventory.add({ nama: 'Pensil', jumlah }), {
      message: 'Jumlah harus bilangan bulat 0 atau lebih.',
    });
  }
  assert.deepEqual(inventory.list(), []);
});

test('update mengganti nama dan jumlah dengan id yang sama', () => {
  const inventory = createInventory(memoryStorage());
  const original = inventory.add({ nama: 'Kursi', jumlah: 3 });

  const updated = inventory.update(original.id, { nama: 'Kursi Lipat', jumlah: 5 });

  assert.deepEqual(updated, { id: original.id, nama: 'Kursi Lipat', jumlah: 5 });
  assert.deepEqual(inventory.list(), [updated]);
});

test('update tidak mengubah barang lain', () => {
  const inventory = createInventory(memoryStorage());
  const kursi = inventory.add({ nama: 'Kursi', jumlah: 3 });
  const meja = inventory.add({ nama: 'Meja', jumlah: 2 });

  inventory.update(kursi.id, { nama: 'Kursi Lipat', jumlah: 4 });

  assert.deepEqual(inventory.list(), [
    { id: kursi.id, nama: 'Kursi Lipat', jumlah: 4 },
    meja,
  ]);
});

test('update menolak id yang tidak ada', () => {
  const inventory = createInventory(memoryStorage());

  assert.throws(() => inventory.update('tidak-ada', { nama: 'Kursi', jumlah: 1 }), {
    message: 'Barang tidak ditemukan.',
  });
});

test('update menolak input tidak valid dan membiarkan data tetap', () => {
  const inventory = createInventory(memoryStorage());
  const kursi = inventory.add({ nama: 'Kursi', jumlah: 3 });

  assert.throws(() => inventory.update(kursi.id, { nama: 'Kursi', jumlah: -2 }), {
    message: 'Jumlah harus bilangan bulat 0 atau lebih.',
  });
  assert.deepEqual(inventory.list(), [kursi]);
});

test('remove menghapus hanya barang yang dipilih', () => {
  const inventory = createInventory(memoryStorage());
  const kursi = inventory.add({ nama: 'Kursi', jumlah: 3 });
  const meja = inventory.add({ nama: 'Meja', jumlah: 2 });

  inventory.remove(kursi.id);

  assert.deepEqual(inventory.list(), [meja]);
});

test('remove menolak id yang tidak ada', () => {
  const inventory = createInventory(memoryStorage());
  inventory.add({ nama: 'Kursi', jumlah: 3 });

  assert.throws(() => inventory.remove('tidak-ada'), {
    message: 'Barang tidak ditemukan.',
  });
  assert.equal(inventory.list().length, 1);
});

test('data rusak di storage dibaca sebagai daftar kosong', () => {
  const storage = memoryStorage();
  storage.setItem(STORAGE_KEY, '{rusak');
  const inventory = createInventory(storage);

  assert.deepEqual(inventory.list(), []);

  inventory.add({ nama: 'Pensil', jumlah: 1 });
  assert.equal(inventory.list().length, 1);
});

test('data tersimpan tetap terbaca oleh instance baru', () => {
  const storage = memoryStorage();
  const item = createInventory(storage).add({ nama: 'Kursi', jumlah: 3 });

  assert.deepEqual(createInventory(storage).list(), [item]);
});

const STORAGE_KEY = 'inventaris.barang';
const NAMA_MAKSIMAL = 100;

function validate(input) {
  const nama = String(input.nama ?? '').trim();
  const teksJumlah = String(input.jumlah ?? '').trim();
  const jumlah = Number(teksJumlah);

  if (nama === '') return 'Nama barang wajib diisi.';
  if (nama.length > NAMA_MAKSIMAL) return `Nama barang maksimal ${NAMA_MAKSIMAL} karakter.`;
  if (teksJumlah === '' || !Number.isInteger(jumlah) || jumlah < 0) {
    return 'Jumlah harus bilangan bulat 0 atau lebih.';
  }
  return null;
}

function createId() {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function toItem(input) {
  const error = validate(input);
  if (error) throw new Error(error);
  return { nama: String(input.nama).trim(), jumlah: Number(input.jumlah) };
}

function createInventory(storage) {
  function readAll() {
    try {
      const items = JSON.parse(storage.getItem(STORAGE_KEY) ?? '[]');
      return Array.isArray(items) ? items : [];
    } catch {
      return [];
    }
  }

  function writeAll(items) {
    storage.setItem(STORAGE_KEY, JSON.stringify(items));
  }

  return {
    list() {
      return readAll();
    },

    add(input) {
      const item = { id: createId(), ...toItem(input) };
      writeAll([...readAll(), item]);
      return item;
    },

    update(id, input) {
      const items = readAll();
      const index = items.findIndex((item) => item.id === id);
      if (index === -1) throw new Error('Barang tidak ditemukan.');

      const item = { id, ...toItem(input) };
      items[index] = item;
      writeAll(items);
      return item;
    },

    remove(id) {
      const items = readAll();
      if (!items.some((item) => item.id === id)) throw new Error('Barang tidak ditemukan.');

      writeAll(items.filter((item) => item.id !== id));
    },
  };
}

const api = { createInventory, STORAGE_KEY };

if (typeof module !== 'undefined') module.exports = api;
if (typeof window !== 'undefined') window.Inventaris = api;

(function () {
  const inventory = Inventaris.createInventory(window.localStorage);

  const form = document.getElementById('form-barang');
  const inputNama = document.getElementById('nama');
  const inputJumlah = document.getElementById('jumlah');
  const formTitle = document.getElementById('judul-form');
  const submitButton = document.getElementById('tombol-simpan');
  const cancelButton = document.getElementById('tombol-batal');
  const message = document.getElementById('pesan');
  const tbody = document.getElementById('daftar-barang');

  let editingId = null;

  function showMessage(text) {
    message.textContent = text;
    message.hidden = text === '';
  }

  function createButton(label, ariaLabel, onClick, className) {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = label;
    button.setAttribute('aria-label', ariaLabel);
    if (className) button.className = className;
    button.addEventListener('click', onClick);
    return button;
  }

  function createRow(item) {
    const row = document.createElement('tr');

    const nameCell = document.createElement('td');
    nameCell.textContent = item.nama;

    const amountCell = document.createElement('td');
    amountCell.className = 'angka';
    amountCell.textContent = item.jumlah;

    const actionCell = document.createElement('td');
    actionCell.className = 'aksi';
    actionCell.append(
      createButton('Ubah', `Ubah ${item.nama}`, () => startEdit(item)),
      createButton('Hapus', `Hapus ${item.nama}`, () => removeItem(item), 'bahaya'),
    );

    row.append(nameCell, amountCell, actionCell);
    return row;
  }

  function render() {
    const items = inventory.list();
    tbody.replaceChildren();

    if (items.length === 0) {
      const row = document.createElement('tr');
      const cell = document.createElement('td');
      cell.colSpan = 3;
      cell.className = 'kosong';
      cell.textContent = 'Belum ada barang. Isi formulir di atas untuk menambah barang pertama.';
      row.append(cell);
      tbody.append(row);
      return;
    }

    tbody.append(...items.map(createRow));
  }

  function resetForm() {
    editingId = null;
    form.reset();
    formTitle.textContent = 'Tambah barang';
    submitButton.textContent = 'Tambah barang';
    cancelButton.hidden = true;
    showMessage('');
  }

  function startEdit(item) {
    editingId = item.id;
    inputNama.value = item.nama;
    inputJumlah.value = item.jumlah;
    formTitle.textContent = 'Ubah barang';
    submitButton.textContent = 'Simpan perubahan';
    cancelButton.hidden = false;
    showMessage('');
    inputNama.focus();
  }

  function removeItem(item) {
    if (!window.confirm(`Hapus barang "${item.nama}"? Tindakan ini tidak bisa dibatalkan.`)) return;

    try {
      inventory.remove(item.id);
    } catch (error) {
      showMessage(error.message);
      return;
    }

    if (editingId === item.id) resetForm();
    render();
  }

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const input = { nama: inputNama.value, jumlah: inputJumlah.value };

    try {
      if (editingId === null) {
        inventory.add(input);
      } else {
        inventory.update(editingId, input);
      }
    } catch (error) {
      showMessage(error.message);
      return;
    }

    resetForm();
    render();
  });

  cancelButton.addEventListener('click', resetForm);

  render();
})();

:root {
  color-scheme: light;
  --latar: #f4f5f7;
  --permukaan: #ffffff;
  --teks: #1f2328;
  --teks-redup: #57606a;
  --garis: #d0d7de;
  --aksen: #1f5fbf;
  --aksen-gelap: #184c99;
  --bahaya: #b42318;

  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--teks);
  background: var(--latar);
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

::selection {
  background: #cfe0f7;
}

*:focus-visible {
  outline: 2px solid var(--aksen);
  outline-offset: 2px;
}

body {
  margin: 0;
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
}

h2 {
  font-size: 1.125rem;
  margin: 0 0 12px;
}

.panel {
  background: var(--permukaan);
  border: 1px solid var(--garis);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}

form {
  display: grid;
  grid-template-columns: 1fr 160px;
  gap: 12px 16px;
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
}

input {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--garis);
  border-radius: 6px;
  background: var(--permukaan);
  color: var(--teks);
  caret-color: var(--aksen);
}

#pesan {
  grid-column: 1 / -1;
  margin: 0;
  font-size: 0.875rem;
  color: var(--bahaya);
}

.actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}

button {
  font: inherit;
  padding: 8px 14px;
  border: 1px solid var(--garis);
  border-radius: 6px;
  background: var(--permukaan);
  color: var(--teks);
  cursor: pointer;
}

button:hover {
  background: #f6f8fa;
}

button:active {
  background: #eaeef2;
}

button[type="submit"] {
  background: var(--aksen);
  border-color: var(--aksen);
  color: #ffffff;
}

button[type="submit"]:hover {
  background: var(--aksen-gelap);
  border-color: var(--aksen-gelap);
}

button.bahaya {
  color: var(--bahaya);
}

button.bahaya:hover {
  background: #fef3f2;
  border-color: var(--bahaya);
}

.wadah-tabel {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 10px 8px;
  border-bottom: 1px solid var(--garis);
  text-align: left;
  vertical-align: middle;
}

th {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--teks-redup);
}

.angka {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.aksi {
  text-align: right;
  white-space: nowrap;
}

.aksi button + button {
  margin-left: 6px;
}

.kosong {
  padding: 24px 8px;
  text-align: center;
  color: var(--teks-redup);
}

@media (max-width: 520px) {
  form {
    grid-template-columns: 1fr;
  }
}
